"""OLED Audio Spectrum Visualizer"""
from espzero import I2SMic, OLED, esp_led
from time import sleep

mic = I2SMic()
oled = OLED(scl=47, sda=21)

while True:
    bands = mic.spectrum(bins=16)
    oled.show_spectrum(bands, title=f"{mic.note or '---'} ({int(mic.decibels)}dB)")

    if (bands[0] + bands[1]) / 2 > 0.4:
        esp_led.color = (255, 0, 128)
    else:
        esp_led.off()

    sleep(0.03)
